        if (IS_THING_ALIVE(*it)) {
            const CTCQuestCard* quest_card = 0;
            (*it)->PeekTC(&quest_card);
            if (quest_card->IsCore() || (quest_card->IsOptional() && !quest_card->GetPDef().IsNull() && !quest_card->GetPDef()->IsVignette)) {
                has_quests = true;
